// src/core/media/presentedFileRecords.ts
function parsePresentedFilesInput(raw) {
  if (!Array.isArray(raw)) return [];
  const files = [];
  for (const entry of raw) {
    if (typeof entry !== "object" || entry === null) continue;
    const { path, description } = entry;
    if (typeof path !== "string" || !path.trim()) continue;
    files.push(typeof description === "string" && description !== "" ? { path: path.trim(), description } : { path: path.trim() });
  }
  return files;
}
var PRESENTED_RESULT_PREFIX = "Presented ";
function parsePresentedResult(result) {
  const paths = [];
  for (const line of result.split("\n")) {
    if (line.trim() === "") continue;
    if (!line.startsWith(PRESENTED_RESULT_PREFIX)) return null;
    paths.push(line.slice(PRESENTED_RESULT_PREFIX.length));
  }
  return paths;
}
function isToolResultError(result) {
  const trimmed = result.trimStart();
  return trimmed.startsWith("Error:") || trimmed.startsWith("Error ");
}
function mediaToolAnnouncedPath(tc) {
  if (!tc.result) return null;
  if (tc.name === TOOL_NAMES.GENERATE_IMAGE) {
    const match = tc.result.match(/(?:图片已保存到|Image saved to): (.+?)(?:\n|$)/);
    return match ? match[1].trim() : null;
  }
  if (tc.name === TOOL_NAMES.PROCESS_IMAGE) {
    const match = tc.result.match(/(?:Image processed successfully|图片处理成功): (.+?)(?:\n|$)/);
    return match ? match[1].trim() : null;
  }
  return null;
}

